+  @override
+  Future<Uri> get callback => _completer.future;
+
+  bool _matches(Uri uri) =>
+      uri.scheme == 'fah' && uri.host == 'oauth' && uri.path == '/network';
+
+  void _complete(Uri uri) {
+    if (!_completer.isCompleted) _completer.complete(uri);
+  }
