/// the RFC 8252 loopback; iOS/Android use the `fah://oauth/network`
/// deep-link callback (the browser cannot reliably reach an on-device
/// loopback).
Future<OAuthCallbackReceiver> startOAuthCallbackReceiverImpl() async {
