/// Binds the receiver to a platform link stream and checks the initial
/// link. The stream subscription attaches BEFORE the initial link is
/// awaited: `AppLinks.uriLinkStream` is a broadcast-style stream, so a
/// link delivered while `getInitialLink()` is still in flight (e.g. an
/// `onNewIntent` during a warm resume) would otherwise be dropped, and a
/// warm resume reports no initial link — the callback would be missed and
/// the flow would wait out the full timeout. A link arriving on both
/// paths is deduped by `_complete`'s `isCompleted` guard.
static Future<DeepLinkOAuthReceiver> bindWithInitialLink({
  required Stream<Uri> links,
  required Future<Uri?> Function() getInitialLink,
  Duration timeout = const Duration(minutes: 3),
}) async {
  final receiver = DeepLinkOAuthReceiver.bind(
    links: links,
    initialLink: null,
    timeout: timeout,
  );
  Uri? initial;
  try {
    initial = await getInitialLink();
  } on Object {
    // Best-effort: the stream listener is the primary path.
    initial = null;
  }
  if (initial != null && receiver.matches(initial)) {
    receiver.complete(initial);
  }
  return receiver;
}
```

