      controller.add(Uri.parse('fah://oauth/networking?code=nope'));
      controller.add(Uri.parse('fah://oauth/network?code=abc&state=xyz'));
      final callback = await pending;
      expect(callback.queryParameters['code'], 'abc');
    });

