      final controller = StreamController<Uri>();
      final receiver = DeepLinkOAuthReceiver.bind(
        links: controller.stream,
        initialLink: null,
      );
      receiver.close();
      receiver.close();
      expect(controller.hasListener, isFalse);
    });

    test('close cancels the timeout timer (no late unhandled error)', () {
      fakeAsync((async) {
        final controller = StreamController<Uri>();
        final receiver = DeepLinkOAuthReceiver.bind(
          links: controller.stream,
          initialLink: null,
