    required Stream<Uri> links,
    required Uri? initialLink,
    Duration timeout = const Duration(minutes: 3),
  }) {
    final receiver = DeepLinkOAuthReceiver._(links);
    receiver._listen(initialLink, timeout);
    return receiver;
  }

